<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue';
import { Head } from '@inertiajs/vue3';
import ErpLayout from '@/layouts/ErpLayout.vue';
import Icon from '@/components/dashboard/Icon.vue';

const props = withDefaults(defineProps<{ userName?: string; userEmail?: string }>(), { userName: '', userEmail: '' });
type Account = { id:number; account_code:string; company_name:string; legal_name:string|null; business_type:string; tier:string; status:string; customer_id:number|null; lead_id:number|null; contact_name:string|null; email:string|null; phone:string|null; tax_id:string|null; registration_number:string|null; payment_terms:string; credit_limit:string|number; default_discount_percent:number; billing_address:string|null; billing_area:string|null; billing_district:string|null; billing_division:string|null; billing_postal_code:string|null; shipping_address:string|null; shipping_area:string|null; shipping_district:string|null; shipping_division:string|null; shipping_postal_code:string|null; notes:string|null; quotes_count?:number; quoted_value?:string|number; customer?:{id:number;customer_code:string;name:string}|null; lead?:{id:number;lead_code:string;name:string;status:string}|null; quotes?:Quote[]; credit_summary?:{payment_terms:string;credit_limit:string;outstanding:string;available_credit:string;utilization_percent:string} };
type Quote = {id:number;quote_number:string;status:string;currency:string;valid_until:string|null;subtotal:string|number;discount_amount:string|number;tax_amount:string|number;total:string|number;items_count?:number;account?:{id:number;account_code:string;company_name:string}};
type Variant = {id:number;product_id:number;name:string|null;sku:string|null;selling_price:string|number;wholesale_price:string|number|null;product?:{id:number;name:string}};
type Api<T> = {data?:T;message?:string;errors?:Record<string,string[]>;stats?:Record<string,number>;current_page?:number;last_page?:number;total?:number;customers?:any[];leads?:any[];variants?:Variant[]};
const tab = ref<'accounts'|'quotes'>('accounts'), loading=ref(false), saving=ref(false), search=ref(''), statusFilter=ref('all'), tierFilter=ref('all'), page=ref(1), lastPage=ref(1), total=ref(0), viewMode=ref<'list'|'grid'>('list');
const accounts=ref<Account[]>([]), quotes=ref<Quote[]>([]), stats=ref({accounts:0,active:0,pending:0,quoted_value:0,open_quotes:0}), quoteStats=ref({total:0,draft:0,sent:0,accepted:0});
const customers=ref<any[]>([]), leads=ref<any[]>([]), variants=ref<Variant[]>([]), notice=ref(''), noticeType=ref<'success'|'error'>('success'), errors=ref<Record<string,string>>({});
const formOpen=ref(false), editing=ref<Account|null>(null), detail=ref<Account|null>(null), deleteTarget=ref<Account|null>(null), quoteOpen=ref(false), quoteDetail=ref<any|null>(null);
const emptyAccount=()=>({company_name:'',legal_name:'',business_type:'retailer',tier:'standard',status:'pending',customer_id:null as number|null,lead_id:null as number|null,contact_name:'',email:'',phone:'',tax_id:'',registration_number:'',payment_terms:'prepaid',credit_limit:0,default_discount_percent:0,billing_address:'',billing_area:'',billing_district:'',billing_division:'',billing_postal_code:'',shipping_address:'',shipping_area:'',shipping_district:'',shipping_division:'',shipping_postal_code:'',notes:''});
const form=reactive(emptyAccount());
type QuoteLine={product_variant_id:number|null;description:string;sku:string;quantity:number;unit_price:number;discount_percent:number};
const quoteForm=reactive({b2b_account_id:null as number|null,currency:'BDT',valid_until:'',discount_amount:0,tax_amount:0,terms:'Prices are valid until the date shown. Supply is subject to stock availability.',notes:'',items:[{product_variant_id:null,description:'',sku:'',quantity:1,unit_price:0,discount_percent:0}] as QuoteLine[]});
const quoteSubtotal=computed(()=>quoteForm.items.reduce((sum,l)=>sum+Math.max(0,Number(l.quantity)||0)*Math.max(0,Number(l.unit_price)||0)*(1-Math.min(100,Math.max(0,Number(l.discount_percent)||0))/100),0));
const quoteTotal=computed(()=>Math.max(0,quoteSubtotal.value-(Number(quoteForm.discount_amount)||0)+(Number(quoteForm.tax_amount)||0)));
function headers(){const csrf=document.querySelector('meta[name="csrf-token"]')?.getAttribute('content')??'';return {Accept:'application/json','Content-Type':'application/json','X-Requested-With':'XMLHttpRequest',...(csrf?{'X-CSRF-TOKEN':csrf}:{})};}
function notify(message:string,type:'success'|'error'='success'){notice.value=message;noticeType.value=type;}
async function requestError(r:Response,fallback:string){const p=await r.json().catch(()=>({})) as Api<unknown>;errors.value=Object.fromEntries(Object.entries(p.errors??{}).map(([k,v])=>[k,v[0]??'Invalid value']));return p.message??Object.values(p.errors??{}).flat()[0]??fallback;}
async function loadOptions(){try{const r=await fetch('/api/v1/backend/b2b/options',{credentials:'same-origin',headers:headers()});if(!r.ok)return;const p=await r.json();customers.value=p.customers??[];leads.value=p.leads??[];variants.value=p.variants??[];}catch{/* keep page usable when optional suggestions are unavailable */}}
async function loadAccounts(){loading.value=true;try{const q=new URLSearchParams({search:search.value,status:statusFilter.value,tier:tierFilter.value,page:String(page.value),per_page:'15'});const r=await fetch(`/api/v1/backend/b2b/accounts?${q}`,{credentials:'same-origin',headers:headers()});if(!r.ok)throw new Error(await requestError(r,'Could not load B2B accounts.'));const p=await r.json() as Api<Account[]>;accounts.value=(p.data as any)?.length!==undefined?p.data as Account[]:((p as any).data?.data??[]); // paginator payload normalization
if(Array.isArray((p as any).data?.data))accounts.value=(p as any).data.data;
lastPage.value=(p as any).last_page??(p as any).data?.last_page??1;total.value=(p as any).total??(p as any).data?.total??accounts.value.length;
const s=(p as any).stats??(p as any).data?.stats;if(s)stats.value=s;
}catch(e){notify(e instanceof Error?e.message:'Could not load accounts.','error');}finally{loading.value=false;}}
async function loadQuotes(){loading.value=true;try{const q=new URLSearchParams({search:search.value,status:statusFilter.value,page:String(page.value)});const r=await fetch(`/api/v1/backend/b2b/quotes?${q}`,{credentials:'same-origin',headers:headers()});if(!r.ok)throw new Error(await requestError(r,'Could not load quotations.'));const p=await r.json();quotes.value=p.data??[];lastPage.value=p.last_page??1;total.value=p.total??0;quoteStats.value=p.stats??{total:0,draft:0,sent:0,accepted:0};}catch(e){notify(e instanceof Error?e.message:'Could not load quotations.','error');}finally{loading.value=false;}}
function refresh(){page.value=1;tab.value==='accounts'?loadAccounts():loadQuotes();}
watch([search,statusFilter,tierFilter],refresh);watch(tab,()=>{search.value='';statusFilter.value='all';tierFilter.value='all';page.value=1;tab.value==='accounts'?loadAccounts():loadQuotes();});
function openCreate(){editing.value=null;Object.assign(form,emptyAccount());errors.value={};formOpen.value=true;}
function fillFromLead(){const lead=leads.value.find(l=>l.id===form.lead_id);if(!lead)return;if(!form.company_name)form.company_name=lead.name||'';if(!form.contact_name)form.contact_name=lead.name||'';if(!form.phone)form.phone=lead.phone||'';if(!form.email)form.email=lead.email||'';}
function openEdit(a:Account){editing.value=a;Object.assign(form,emptyAccount(),Object.fromEntries(Object.keys(emptyAccount()).map(k=>[k,(a as any)[k]??(emptyAccount() as any)[k]])));errors.value={};formOpen.value=true;}
async function saveAccount(){saving.value=true;errors.value={};try{const r=await fetch(editing.value?`/api/v1/backend/b2b/accounts/${editing.value.id}`:'/api/v1/backend/b2b/accounts',{method:editing.value?'PUT':'POST',credentials:'same-origin',headers:headers(),body:JSON.stringify(form)});if(!r.ok)throw new Error(await requestError(r,'Could not save account.'));const p=await r.json();formOpen.value=false;notify(p.message??'Account saved.');await Promise.all([loadAccounts(),loadOptions()]);}catch(e){notify(e instanceof Error?e.message:'Could not save account.','error');}finally{saving.value=false;}}
async function showAccount(a:Account){try{const r=await fetch(`/api/v1/backend/b2b/accounts/${a.id}`,{credentials:'same-origin',headers:headers()});if(!r.ok)throw new Error(await requestError(r,'Could not load account details.'));detail.value=(await r.json()).data;}catch(e){notify(e instanceof Error?e.message:'Could not load details.','error');}}
async function deleteAccount(){if(!deleteTarget.value)return;try{const r=await fetch(`/api/v1/backend/b2b/accounts/${deleteTarget.value.id}`,{method:'DELETE',credentials:'same-origin',headers:headers()});if(!r.ok)throw new Error(await requestError(r,'Could not delete account.'));notify((await r.json()).message??'Account deleted.');deleteTarget.value=null;await loadAccounts();}catch(e){notify(e instanceof Error?e.message:'Could not delete account.','error');}}
function addQuoteLine(){quoteForm.items.push({product_variant_id:null,description:'',sku:'',quantity:1,unit_price:0,discount_percent:0});}
function selectVariant(line:QuoteLine){const v=variants.value.find(x=>x.id===line.product_variant_id);if(!v)return;line.description=[v.product?.name,v.name].filter(Boolean).join(' — ')||v.sku||'Product';line.sku=v.sku??'';line.unit_price=Number(v.wholesale_price??v.selling_price??0);}
function openQuote(){Object.assign(quoteForm,{b2b_account_id:accounts.value.find(a=>a.status==='active')?.id??accounts.value[0]?.id??null,currency:'BDT',valid_until:'',discount_amount:0,tax_amount:0,terms:'Prices are valid until the date shown. Supply is subject to stock availability.',notes:'',items:[{product_variant_id:null,description:'',sku:'',quantity:1,unit_price:0,discount_percent:0}]});errors.value={};quoteOpen.value=true;}
async function saveQuote(){saving.value=true;errors.value={};try{const r=await fetch('/api/v1/backend/b2b/quotes',{method:'POST',credentials:'same-origin',headers:headers(),body:JSON.stringify(quoteForm)});if(!r.ok)throw new Error(await requestError(r,'Could not create quotation.'));const p=await r.json();quoteOpen.value=false;tab.value='quotes';notify(p.message??'Quotation created.');await loadQuotes();}catch(e){notify(e instanceof Error?e.message:'Could not create quotation.','error');}finally{saving.value=false;}}
async function changeQuoteStatus(q:Quote,status:string){try{const r=await fetch(`/api/v1/backend/b2b/quotes/${q.id}/status`,{method:'PATCH',credentials:'same-origin',headers:headers(),body:JSON.stringify({status})});if(!r.ok)throw new Error(await requestError(r,'Could not update quotation.'));notify((await r.json()).message??'Quotation updated.');await loadQuotes();}catch(e){notify(e instanceof Error?e.message:'Could not update quotation.','error');}}
async function showQuote(q:Quote){try{const r=await fetch(`/api/v1/backend/b2b/quotes/${q.id}`,{credentials:'same-origin',headers:headers()});if(!r.ok)throw new Error(await requestError(r,'Could not load quotation.'));quoteDetail.value=(await r.json()).data;}catch(e){notify(e instanceof Error?e.message:'Could not load quotation.','error');}}
function money(value:number|string,currency='BDT'){return new Intl.NumberFormat('en-BD',{style:'currency',currency,maximumFractionDigits:2}).format(Number(value)||0);}
function pretty(value:string){return value.replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());}
function clearFilters(){search.value='';statusFilter.value='all';tierFilter.value='all';page.value=1;}
function exportRecords(){
  const rows = tab.value === 'accounts'
    ? [['Account code','Company','Legal name','Business type','Tier','Status','Contact','Email','Phone','Payment terms','Credit limit','Default discount (%)','Customer code','Lead code'], ...accounts.value.map(a => [a.account_code,a.company_name,a.legal_name??'',a.business_type,a.tier,a.status,a.contact_name??'',a.email??'',a.phone??'',a.payment_terms,a.credit_limit,a.default_discount_percent,a.customer?.customer_code??'',a.lead?.lead_code??''])]
    : [['Quote number','Company','Account code','Status','Currency','Valid until','Items','Subtotal','Discount','Tax / charges','Total'], ...quotes.value.map(q => [q.quote_number,q.account?.company_name??'',q.account?.account_code??'',q.status,q.currency,q.valid_until??'',q.items_count??'',q.subtotal,q.discount_amount,q.tax_amount,q.total])];
  const csv = rows.map(row => row.map(value => { const text = String(value ?? ''); return /[",\r\n]/.test(text) ? '"' + text.replaceAll('"','""') + '"' : text; }).join(',')).join('\r\n');
  const blob = new Blob(['\ufeff', csv], {type:'text/csv;charset=utf-8;'});
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a'); link.href = url; link.download = tab.value === 'accounts' ? 'b2b-business-accounts.csv' : 'b2b-quotations.csv';
  document.body.appendChild(link); link.click(); link.remove(); URL.revokeObjectURL(url);
}
onMounted(()=>{loadOptions();loadAccounts();});
</script>

<template>
  <Head title="B2B & Wholesale" />
  <ErpLayout :user-name="props.userName" :user-email="props.userEmail">
    <main class="b2b-page">
      <header class="page-head"><div><div class="crumb">Sales <Icon name="chevron-right" :size="12"/><b>B2B &amp; Wholesale</b></div><div class="title-line"><div class="hero-icon"><Icon name="building-2" :size="23"/></div><div><h1>B2B &amp; Wholesale</h1><p>Manage business accounts, commercial terms and the quotation-to-order pipeline.</p></div></div></div><div class="head-actions"><button class="btn secondary" @click="openQuote"><Icon name="file-plus-2" :size="15"/> Create quotation</button><button class="btn primary" @click="openCreate"><Icon name="building-2" :size="15"/> Add business account</button></div></header>
      <div v-if="notice" class="notice" :class="noticeType" role="status"><Icon :name="noticeType==='success'?'check-circle':'alert-circle'" :size="16"/>{{notice}}<button @click="notice=''" aria-label="Dismiss"><Icon name="x" :size="14"/></button></div>
      <nav class="tabs"><button :class="{active:tab==='accounts'}" @click="tab='accounts'"><Icon name="building-2" :size="15"/> Business accounts <span>{{stats.accounts}}</span></button><button :class="{active:tab==='quotes'}" @click="tab='quotes'"><Icon name="file-text" :size="15"/> Quotations <span>{{quoteStats.total}}</span></button></nav>
      <section v-if="tab==='accounts'" class="stats"><article><div class="metric-top"><span>Total accounts</span><span class="metric-icon blue"><Icon name="building-2" :size="19"/></span></div><strong>{{stats.accounts}}</strong><small>Business relationships</small></article><article><div class="metric-top"><span>Active accounts</span><span class="metric-icon teal"><Icon name="badge-check" :size="19"/></span></div><strong>{{stats.active}}</strong><small>Approved to trade</small></article><article><div class="metric-top"><span>Pending approval</span><span class="metric-icon amber"><Icon name="clock-3" :size="19"/></span></div><strong>{{stats.pending}}</strong><small>Awaiting review</small></article><article><div class="metric-top"><span>Open quote value</span><span class="metric-icon violet"><Icon name="chart-no-axes-combined" :size="19"/></span></div><strong>{{money(stats.quoted_value)}}</strong><small>Non-rejected quotations</small></article></section>
      <section v-else class="stats"><article><div class="metric-top"><span>Total quotations</span><span class="metric-icon blue"><Icon name="files" :size="19"/></span></div><strong>{{quoteStats.total}}</strong><small>All quote records</small></article><article><div class="metric-top"><span>Drafts</span><span class="metric-icon violet"><Icon name="file-pen-line" :size="19"/></span></div><strong>{{quoteStats.draft}}</strong><small>Not yet sent</small></article><article><div class="metric-top"><span>Sent / reviewing</span><span class="metric-icon amber"><Icon name="send" :size="19"/></span></div><strong>{{quoteStats.sent}}</strong><small>Awaiting customer response</small></article><article><div class="metric-top"><span>Accepted</span><span class="metric-icon teal"><Icon name="check-circle-2" :size="19"/></span></div><strong>{{quoteStats.accepted}}</strong><small>Commercially accepted</small></article></section>
      <section class="panel"><header class="directory-head"><div class="directory-title"><span class="directory-icon"><Icon :name="tab==='accounts'?'building-2':'file-text'" :size="19"/></span><div><h2>{{tab==='accounts'?'Business account directory':'Quotation register'}}</h2><p>{{tab==='accounts'?'Search and manage wholesale buyers, tiers, credit and CRM links.':'Track quote value, validity and customer decisions.'}}</p></div></div><div class="directory-actions"><button class="btn secondary" @click="tab==='accounts'?loadAccounts():loadQuotes()" :disabled="loading"><Icon name="refresh-cw" :size="14"/> Refresh</button><button class="btn ghost export-btn" @click="exportRecords" :disabled="loading||!(tab==='accounts'?accounts.length:quotes.length)"><Icon name="download" :size="14"/> Export CSV</button><div v-if="tab==='accounts'" class="view-switch" aria-label="Directory view"><button :class="{selected:viewMode==='list'}" :aria-pressed="viewMode==='list'" @click="viewMode='list'" title="List view"><Icon name="list" :size="15"/><span>List</span></button><button :class="{selected:viewMode==='grid'}" :aria-pressed="viewMode==='grid'" @click="viewMode='grid'" title="Grid view"><Icon name="layout-grid" :size="15"/><span>Grid</span></button></div></div></header><div class="directory-filters"><label class="search"><Icon name="search" :size="16"/><input v-model="search" :placeholder="tab==='accounts'?'Search company, code, contact, email or phone…':'Search quote or company…'"/><button v-if="search" @click="search=''" aria-label="Clear search"><Icon name="x" :size="14"/></button></label><select v-model="statusFilter" aria-label="Filter status"><option value="all">All statuses</option><option v-if="tab==='accounts'" value="pending">Pending</option><option v-if="tab==='accounts'" value="active">Active</option><option v-if="tab==='accounts'" value="on_hold">On hold</option><option v-if="tab==='accounts'" value="inactive">Inactive</option><option v-if="tab==='quotes'" value="draft">Draft</option><option v-if="tab==='quotes'" value="sent">Sent</option><option v-if="tab==='quotes'" value="under_review">Under review</option><option v-if="tab==='quotes'" value="accepted">Accepted</option><option v-if="tab==='quotes'" value="rejected">Rejected</option><option v-if="tab==='quotes'" value="expired">Expired</option></select><select v-if="tab==='accounts'" v-model="tierFilter" aria-label="Filter tier"><option value="all">All tiers</option><option value="standard">Standard</option><option value="silver">Silver</option><option value="gold">Gold</option><option value="platinum">Platinum</option></select><button class="clear-filters" v-if="search||statusFilter!=='all'||tierFilter!=='all'" @click="clearFilters"><Icon name="x" :size="14"/> Clear filters</button></div>
        <div v-if="loading" class="state"><Icon name="loader-circle" :size="20"/> Loading records…</div>
        <div v-else-if="tab==='accounts'&&viewMode==='grid'" class="account-grid"><article v-for="a in accounts" :key="a.id" class="account-card"><div class="account-card-top"><span class="account-avatar"><Icon name="building-2" :size="19"/></span><span class="status" :class="a.status">{{pretty(a.status)}}</span></div><button class="entity-link account-card-name" @click="showAccount(a)">{{a.company_name}}</button><small class="subline">{{a.account_code}}</small><div class="account-card-contact"><Icon name="user-round" :size="14"/><span>{{a.contact_name||'No primary contact'}}</span></div><div class="account-card-meta"><span class="tier" :class="a.tier">{{pretty(a.tier)}}</span><strong>{{money(a.credit_limit)}}</strong></div><div class="account-card-actions"><button class="icon-btn" title="View account" @click="showAccount(a)"><Icon name="eye" :size="16"/></button><button class="icon-btn" title="Edit account" @click="openEdit(a)"><Icon name="pencil" :size="16"/></button><button class="icon-btn danger" title="Delete account" @click="deleteTarget=a"><Icon name="trash-2" :size="16"/></button></div></article><div v-if="!accounts.length" class="empty grid-empty"><Icon name="building-2" :size="26"/><strong>No business accounts found</strong><span>Try changing your filters or add your first wholesale account.</span><button class="btn primary" @click="openCreate">Add business account</button></div></div><div v-else-if="tab==='accounts'" class="table-wrap"><table><thead><tr><th>Business</th><th>Primary contact</th><th>Tier / terms</th><th>Credit limit</th><th>CRM relationship</th><th>Status</th><th class="right">Actions</th></tr></thead><tbody><tr v-for="a in accounts" :key="a.id"><td><button class="entity-link" @click="showAccount(a)">{{a.company_name}}</button><small class="subline">{{a.account_code}} <span v-if="a.quotes_count">· {{a.quotes_count}} quotes</span></small></td><td><strong>{{a.contact_name||'—'}}</strong><small class="subline">{{a.email||a.phone||'No contact details'}}</small></td><td><span class="tier" :class="a.tier">{{pretty(a.tier)}}</span><small class="subline">{{pretty(a.payment_terms)}} · {{a.default_discount_percent}}% default discount</small></td><td><strong>{{money(a.credit_limit)}}</strong></td><td><template v-if="a.customer"><span class="link-chip">Customer · {{a.customer.customer_code}}</span><small class="subline">{{a.customer.name}}</small></template><template v-else-if="a.lead"><span class="link-chip lead">Lead · {{a.lead.lead_code}}</span><small class="subline">{{a.lead.name}}</small></template><span v-else class="muted">Not linked</span></td><td><span class="status" :class="a.status">{{pretty(a.status)}}</span></td><td><div class="row-actions"><button class="icon-btn" title="View account" @click="showAccount(a)"><Icon name="eye" :size="16"/></button><button class="icon-btn" title="Edit account" @click="openEdit(a)"><Icon name="pencil" :size="16"/></button><button class="icon-btn danger" title="Delete account" @click="deleteTarget=a"><Icon name="trash-2" :size="16"/></button></div></td></tr><tr v-if="!accounts.length"><td colspan="7"><div class="empty"><Icon name="building-2" :size="26"/><strong>No business accounts found</strong><span>Try changing your filters or add your first wholesale account.</span><button class="btn primary" @click="openCreate">Add business account</button></div></td></tr></tbody></table></div>
        <div v-else class="table-wrap"><table><thead><tr><th>Quotation</th><th>Business account</th><th>Valid until</th><th>Items</th><th>Total</th><th>Status</th><th class="right">Actions</th></tr></thead><tbody><tr v-for="q in quotes" :key="q.id"><td><button class="entity-link" @click="showQuote(q)">{{q.quote_number}}</button><small class="subline">{{q.currency}} · created quotation</small></td><td><strong>{{q.account?.company_name||'Unknown account'}}</strong><small class="subline">{{q.account?.account_code}}</small></td><td>{{q.valid_until||'No expiry'}}</td><td>{{q.items_count??'—'}}</td><td><strong>{{money(q.total,q.currency)}}</strong></td><td><span class="status" :class="q.status">{{pretty(q.status)}}</span></td><td><div class="row-actions"><button class="icon-btn" title="View quotation" @click="showQuote(q)"><Icon name="eye" :size="16"/></button><button v-if="q.status==='draft'" class="icon-btn" title="Mark sent" @click="changeQuoteStatus(q,'sent')"><Icon name="send" :size="16"/></button><button v-if="['sent','under_review'].includes(q.status)" class="icon-btn" title="Mark accepted" @click="changeQuoteStatus(q,'accepted')"><Icon name="check" :size="16"/></button></div></td></tr><tr v-if="!quotes.length"><td colspan="7"><div class="empty"><Icon name="file-text" :size="26"/><strong>No quotations found</strong><span>Create a quote for an active business account to begin.</span><button class="btn primary" @click="openQuote">Create quotation</button></div></td></tr></tbody></table></div>
        <footer class="pagination"><span>Showing {{tab==='accounts'?accounts.length:quotes.length}} of {{total}} records</span><div><button class="btn ghost" :disabled="page<=1" @click="page--;tab==='accounts'?loadAccounts():loadQuotes()">Previous</button><span>Page {{page}} of {{lastPage}}</span><button class="btn ghost" :disabled="page>=lastPage" @click="page++;tab==='accounts'?loadAccounts():loadQuotes()">Next</button></div></footer>
      </section>
    </main>
    <div v-if="formOpen" class="overlay" @click.self="formOpen=false"><section class="modal wide"><header class="modal-head"><div><span class="eyebrow">BUSINESS PROFILE</span><h2>{{editing?'Edit business account':'Create business account'}}</h2><p>Commercial identity, CRM linkage, credit and delivery preferences.</p></div><button class="icon-btn" @click="formOpen=false"><Icon name="x" :size="18"/></button></header><form @submit.prevent="saveAccount"><div class="form-grid"><label class="field span2"><span>Company name *</span><input v-model="form.company_name" required maxlength="180" placeholder="e.g. Rahman Trading Co."/><small v-if="errors.company_name" class="field-error">{{errors.company_name}}</small></label><label class="field"><span>Legal name</span><input v-model="form.legal_name" maxlength="180" placeholder="Registered legal entity"/></label><label class="field"><span>Business type *</span><select v-model="form.business_type"><option value="retailer">Retailer</option><option value="distributor">Distributor</option><option value="reseller">Reseller</option><option value="corporate">Corporate</option><option value="institution">Institution</option><option value="other">Other</option></select></label><label class="field"><span>Account tier *</span><select v-model="form.tier"><option value="standard">Standard</option><option value="silver">Silver</option><option value="gold">Gold</option><option value="platinum">Platinum</option></select></label><label class="field"><span>Account status *</span><select v-model="form.status"><option value="pending">Pending approval</option><option value="active">Active</option><option value="on_hold">On hold</option><option value="inactive">Inactive</option></select></label><div class="section-label span2">Primary contact</div><label class="field"><span>Contact name</span><input v-model="form.contact_name" maxlength="160"/></label><label class="field"><span>Business email</span><input v-model="form.email" type="email" maxlength="190"/><small v-if="errors.email" class="field-error">{{errors.email}}</small></label><label class="field"><span>Phone</span><input v-model="form.phone" maxlength="40" placeholder="+880…"/><small v-if="errors.phone" class="field-error">{{errors.phone}}</small></label><label class="field"><span>Tax ID / BIN</span><input v-model="form.tax_id" maxlength="100"/></label><label class="field"><span>Registration number</span><input v-model="form.registration_number" maxlength="100"/></label><div class="section-label span2">Connect with Sales CRM</div><label class="field"><span>Existing customer</span><select v-model="form.customer_id"><option :value="null">No linked customer</option><option v-for="c in customers" :key="c.id" :value="c.id">{{c.customer_code}} — {{c.company_name||c.name}}</option></select><small v-if="errors.customer_id" class="field-error">{{errors.customer_id}}</small></label><label class="field"><span>B2B lead</span><select v-model="form.lead_id" @change="fillFromLead"><option :value="null">No linked lead</option><option v-for="l in leads" :key="l.id" :value="l.id">{{l.lead_code}} — {{l.name}}</option></select><small v-if="errors.lead_id" class="field-error">{{errors.lead_id}}</small></label><div class="section-label span2">Commercial terms</div><label class="field"><span>Payment terms *</span><select v-model="form.payment_terms"><option value="prepaid">Prepaid</option><option value="cod">Cash on delivery</option><option value="net_7">Net 7 days</option><option value="net_15">Net 15 days</option><option value="net_30">Net 30 days</option><option value="net_60">Net 60 days</option></select></label><label class="field"><span>Credit limit (BDT) *</span><input v-model.number="form.credit_limit" type="number" min="0" step="0.01" required/><small v-if="errors.credit_limit" class="field-error">{{errors.credit_limit}}</small></label><label class="field"><span>Default discount (%) *</span><input v-model.number="form.default_discount_percent" type="number" min="0" max="100" step="1" required/></label><div class="section-label span2">Billing address</div><label class="field span2"><span>Address</span><input v-model="form.billing_address" maxlength="500"/></label><label class="field"><span>Area / Upazila</span><input v-model="form.billing_area" maxlength="120"/></label><label class="field"><span>District</span><input v-model="form.billing_district" maxlength="120"/></label><label class="field"><span>Division</span><input v-model="form.billing_division" maxlength="120"/></label><label class="field"><span>Postal code</span><input v-model="form.billing_postal_code" maxlength="20"/></label><div class="section-label span2">Shipping address <span class="optional">(if different)</span></div><label class="field span2"><span>Address</span><input v-model="form.shipping_address" maxlength="500"/></label><label class="field"><span>Area / Upazila</span><input v-model="form.shipping_area" maxlength="120"/></label><label class="field"><span>District</span><input v-model="form.shipping_district" maxlength="120"/></label><label class="field"><span>Division</span><input v-model="form.shipping_division" maxlength="120"/></label><label class="field"><span>Postal code</span><input v-model="form.shipping_postal_code" maxlength="20"/></label><label class="field span2"><span>Internal notes</span><textarea v-model="form.notes" rows="3" maxlength="10000" placeholder="Onboarding notes, buying preferences, approval context…"/></label></div><footer class="modal-foot"><button type="button" class="btn ghost" @click="formOpen=false">Cancel</button><button type="submit" class="btn primary" :disabled="saving"><Icon name="check" :size="15"/> {{saving?'Saving…':editing?'Save changes':'Create account'}}</button></footer></form></section></div>
    <div v-if="quoteOpen" class="overlay" @click.self="quoteOpen=false"><section class="modal wide"><header class="modal-head"><div><span class="eyebrow">COMMERCIAL DOCUMENT</span><h2>Create quotation</h2><p>Build a priced proposal for a business account. The quote is saved as a draft.</p></div><button class="icon-btn" @click="quoteOpen=false"><Icon name="x" :size="18"/></button></header><form @submit.prevent="saveQuote"><div class="form-grid"><label class="field span2"><span>Business account *</span><select v-model="quoteForm.b2b_account_id" required><option :value="null" disabled>Select an account</option><option v-for="a in accounts.filter(x=>x.status==='active')" :key="a.id" :value="a.id">{{a.account_code}} — {{a.company_name}}</option></select><small v-if="!accounts.some(a=>a.status==='active')" class="field-error">An active business account is required before creating a quotation.</small></label><label class="field"><span>Currency</span><select v-model="quoteForm.currency"><option value="BDT">BDT — Bangladeshi Taka</option><option value="USD">USD — US Dollar</option><option value="EUR">EUR — Euro</option></select></label><label class="field"><span>Valid until</span><input v-model="quoteForm.valid_until" type="date" :min="new Date().toISOString().slice(0,10)"/></label><div class="section-label span2">Quote line items</div><div class="quote-lines span2"><div v-for="(line,i) in quoteForm.items" :key="i" class="quote-line"><label class="field"><span>Catalog variant</span><select v-model="line.product_variant_id" @change="selectVariant(line)"><option :value="null">Custom line item</option><option v-for="v in variants" :key="v.id" :value="v.id">{{v.product?.name||'Product'}} · {{v.name||v.sku||`Variant ${v.id}`}}</option></select></label><label class="field"><span>Description *</span><input v-model="line.description" required maxlength="240"/></label><label class="field"><span>SKU</span><input v-model="line.sku" maxlength="100"/></label><label class="field"><span>Qty *</span><input v-model.number="line.quantity" type="number" min="0.001" step="0.001" required/></label><label class="field"><span>Unit price *</span><input v-model.number="line.unit_price" type="number" min="0" step="0.01" required/></label><label class="field"><span>Line discount %</span><input v-model.number="line.discount_percent" type="number" min="0" max="100" step="0.01"/></label><button v-if="quoteForm.items.length>1" type="button" class="icon-btn danger remove-line" @click="quoteForm.items.splice(i,1)" title="Remove line"><Icon name="trash-2" :size="15"/></button></div><button type="button" class="btn ghost" @click="addQuoteLine"><Icon name="plus" :size="15"/> Add line item</button></div><label class="field"><span>Additional quote discount ({{quoteForm.currency}})</span><input v-model.number="quoteForm.discount_amount" type="number" min="0" step="0.01"/></label><label class="field"><span>Tax / charges ({{quoteForm.currency}})</span><input v-model.number="quoteForm.tax_amount" type="number" min="0" step="0.01"/></label><label class="field span2"><span>Commercial terms</span><textarea v-model="quoteForm.terms" rows="2" maxlength="5000"/></label><label class="field span2"><span>Internal notes</span><textarea v-model="quoteForm.notes" rows="2" maxlength="5000"/></label><div class="quote-total span2"><div><span>Net subtotal</span><strong>{{money(quoteSubtotal,quoteForm.currency)}}</strong></div><div><span>Quote total</span><strong>{{money(quoteTotal,quoteForm.currency)}}</strong></div></div></div><small v-if="errors.items" class="field-error">{{errors.items}}</small><footer class="modal-foot"><button type="button" class="btn ghost" @click="quoteOpen=false">Cancel</button><button type="submit" class="btn primary" :disabled="saving||!accounts.some(a=>a.status==='active')"><Icon name="file-check" :size="15"/> {{saving?'Saving…':'Save draft quotation'}}</button></footer></form></section></div>
    <div v-if="detail" class="overlay" @click.self="detail=null"><section class="modal"><header class="modal-head"><div><span class="eyebrow">{{detail.account_code}}</span><h2>{{detail.company_name}}</h2><p>{{pretty(detail.business_type)}} · {{pretty(detail.tier)}} tier</p></div><button class="icon-btn" @click="detail=null"><Icon name="x" :size="18"/></button></header><div class="detail-grid"><div><span>Status</span><strong><span class="status" :class="detail.status">{{pretty(detail.status)}}</span></strong></div><div><span>Credit limit</span><strong>{{money(detail.credit_limit)}}</strong></div><div><span>Outstanding credit</span><strong>{{money(detail.credit_summary?.outstanding??0)}}</strong></div><div><span>Available credit</span><strong>{{money(detail.credit_summary?.available_credit??detail.credit_limit)}}</strong></div><div><span>Credit utilization</span><strong>{{detail.credit_summary?.utilization_percent??'0.00'}}%</strong></div><div><span>Payment terms</span><strong>{{pretty(detail.payment_terms)}}</strong></div><div><span>Default discount</span><strong>{{detail.default_discount_percent}}%</strong></div><div><span>Primary contact</span><strong>{{detail.contact_name||'—'}}</strong><small>{{detail.email||detail.phone||''}}</small></div><div><span>CRM customer</span><strong>{{detail.customer?.customer_code||'Not linked'}}</strong><small>{{detail.customer?.name||''}}</small></div><div><span>Linked lead</span><strong>{{detail.lead?.lead_code||'Not linked'}}</strong><small>{{detail.lead?.name||''}}</small></div><div><span>Tax / BIN</span><strong>{{detail.tax_id||'—'}}</strong></div><div class="span2"><span>Billing address</span><strong>{{[detail.billing_address,detail.billing_area,detail.billing_district,detail.billing_division,detail.billing_postal_code].filter(Boolean).join(', ')||'Not provided'}}</strong></div><div class="span2"><span>Shipping address</span><strong>{{[detail.shipping_address,detail.shipping_area,detail.shipping_district,detail.shipping_division,detail.shipping_postal_code].filter(Boolean).join(', ')||'Same as billing / not provided'}}</strong></div><div class="span2"><span>Notes</span><p>{{detail.notes||'No internal notes.'}}</p></div><div class="span2"><span>Recent quotations</span><div v-if="detail.quotes?.length" class="mini-quotes"><div v-for="q in detail.quotes" :key="q.id"><strong>{{q.quote_number}}</strong><span>{{money(q.total,q.currency)}}</span><span class="status" :class="q.status">{{pretty(q.status)}}</span></div></div><p v-else>No quotations created yet.</p></div></div><footer class="modal-foot"><button class="btn ghost" @click="detail=null">Close</button><button class="btn primary" @click="openEdit(detail);detail=null"><Icon name="pencil" :size="15"/> Edit account</button></footer></section></div>
    <div v-if="quoteDetail" class="overlay" @click.self="quoteDetail=null"><section class="modal"><header class="modal-head"><div><span class="eyebrow">{{quoteDetail.quote_number}}</span><h2>Quotation details</h2><p>{{quoteDetail.account?.company_name}}</p></div><button class="icon-btn" @click="quoteDetail=null"><Icon name="x" :size="18"/></button></header><div class="detail-grid"><div><span>Status</span><strong><span class="status" :class="quoteDetail.status">{{pretty(quoteDetail.status)}}</span></strong></div><div><span>Valid until</span><strong>{{quoteDetail.valid_until||'No expiry'}}</strong></div><div class="span2"><span>Line items</span><div class="mini-quotes"><div v-for="line in quoteDetail.items" :key="line.id"><strong>{{line.description}}</strong><span>{{line.quantity}} × {{money(line.unit_price,quoteDetail.currency)}}</span><span>{{money(line.line_total,quoteDetail.currency)}}</span></div></div></div><div><span>Subtotal</span><strong>{{money(quoteDetail.subtotal,quoteDetail.currency)}}</strong></div><div><span>Additional discount</span><strong>−{{money(quoteDetail.discount_amount,quoteDetail.currency)}}</strong></div><div><span>Tax / charges</span><strong>{{money(quoteDetail.tax_amount,quoteDetail.currency)}}</strong></div><div><span>Total</span><strong class="total-amount">{{money(quoteDetail.total,quoteDetail.currency)}}</strong></div><div class="span2"><span>Commercial terms</span><p>{{quoteDetail.terms||'—'}}</p></div><div class="span2"><span>Notes</span><p>{{quoteDetail.notes||'—'}}</p></div></div><footer class="modal-foot"><button class="btn ghost" @click="quoteDetail=null">Close</button><button v-if="quoteDetail.status==='draft'" class="btn primary" @click="changeQuoteStatus(quoteDetail,'sent');quoteDetail=null"><Icon name="send" :size="15"/> Mark as sent</button><button v-if="['sent','under_review'].includes(quoteDetail.status)" class="btn primary" @click="changeQuoteStatus(quoteDetail,'accepted');quoteDetail=null"><Icon name="check" :size="15"/> Mark accepted</button></footer></section></div>
    <div v-if="deleteTarget" class="overlay" @click.self="deleteTarget=null"><section class="modal confirm"><div class="confirm-icon"><Icon name="alert-triangle" :size="24"/></div><h2>Delete business account?</h2><p>You're about to delete <strong>{{deleteTarget.company_name}}</strong>. Accounts with quotation history cannot be deleted; mark those inactive instead.</p><footer class="modal-foot"><button class="btn ghost" @click="deleteTarget=null">Cancel</button><button class="btn danger-btn" @click="deleteAccount">Delete account</button></footer></section></div>
  </ErpLayout>
</template>

